<?php $title='Shop products'; require 'includes/header.php'; $q=trim($_GET['q']??''); $cat=$_GET['category']??''; $sql='SELECT * FROM products WHERE 1';$args=[];if($q){$sql.=' AND (name LIKE ? OR category LIKE ? OR description LIKE ?)';$args=["%$q%","%$q%","%$q%"];}$cats=['Electronics','Wearables','Fashion','Home'];if($cat){$sql.=' AND category=?';$args[]=$cat;}$sql.=' ORDER BY created_at DESC';$s=$pdo->prepare($sql);$s->execute($args);$items=$s->fetchAll(); ?>
<section class="container section"><div class="sectionHead"><div><span class="eyebrow">SHOP</span><h1>Find your next favorite</h1><p><?=count($items)?> products available</p></div></div><div class="chips"><a class="chip" href="products.php">All</a><?php foreach($cats as $c):?><a class="chip" href="?category=<?=urlencode($c)?>"><?=e($c)?></a><?php endforeach;?></div><div class="grid4"><?php foreach($items as $p): ?><?=product_card($p)?><?php endforeach;?></div></section><?php function product_card($p){ob_start(); ?><article class="card"><div class="productImg"><img src="assets/images/<?=e($p['image'])?>"><span><?=e($p['badge'])?></span></div><div class="cardbody"><small><?=e($p['category'])?></small><h3><?=e($p['name'])?></h3><div class="rating">★ <?=e($p['rating'])?></div><div class="price">₹<?=number_format($p['price'])?> <del>₹<?=number_format($p['old_price'])?></del></div><form method="post" action="actions/cart.php"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="action" value="add"><button class="btn dark full">Add to cart</button></form></div></article><?php return ob_get_clean();} require 'includes/footer.php'; ?>